export function generateEntranceQuiz(): EntranceQuizQuestion[] {
  return shuffleArray(questions)
}

export function getEntranceQuizParts(): { partNumber: number; partTitle: string }[] {
  return [
    { partNumber: 1, partTitle: "What Connector Items Look Like" },
    { partNumber: 2, partTitle: "Finding the Lettered Points" },
    { partNumber: 3, partTitle: "Turned Shapes: Rotation Without Flipping" },
    { partNumber: 4, partTitle: "Checking the Connector Line" },
    { partNumber: 5, partTitle: "Look-Alike Shapes and Size Traps" },
    { partNumber: 6, partTitle: "Strategy, Timing and Traps" },
    { partNumber: 7, partTitle: "Mastery Check" },
  ]
}
